export function getComoComiTier(name: string): boolean {
  return COMO_COMI_PICKS.some(p => name.toLowerCase().includes(p.toLowerCase()))
}

export function generateDescription(name: string, category: string, rating: number, priceLevel: number, hot: number, city = 'austin'): string {
  const isStar = [...MICHELIN_STAR, ...MTY_MICHELIN_STAR, ...ATL_MICHELIN_STAR, ...NYC_MICHELIN_STAR_3, ...NYC_MICHELIN_STAR_2, ...NYC_MICHELIN_STAR_1, ...DAL_MICHELIN_STAR, ...MIA_MICHELIN_STAR, ...CDMX_MICHELIN_STAR, ...CHI_MICHELIN_STAR_3, ...CHI_MICHELIN_STAR_2, ...CHI_MICHELIN_STAR_1, ...LA_MICHELIN_STAR_3, ...LA_MICHELIN_STAR_2, ...LA_MICHELIN_STAR_1].some(m => name.toLowerCase().includes(m.toLowerCase()))
  const isBib  = [...MICHELIN_BIB, ...MTY_MICHELIN_BIB, ...ATL_MICHELIN_BIB, ...NYC_MICHELIN_BIB, ...DAL_MICHELIN_BIB, ...MIA_MICHELIN_BIB, ...CDMX_MICHELIN_BIB, ...CHI_MICHELIN_BIB, ...LA_MICHELIN_BIB].some(m => name.toLowerCase().includes(m.toLowerCase()))
  const cityLabel = city === 'monterrey' ? 'Monterrey' : city === 'atlanta' ? 'Atlanta' : city === 'nyc' ? 'New York' : city === 'dallas' ? 'Dallas' : city === 'miami' ? 'Miami' : city === 'cdmx' ? 'Ciudad de México' : city === 'chicago' ? 'Chicago' : city === 'la' ? 'Los Angeles' : city === 'houston' ? 'Houston' : 'Austin'

  if (isStar) return `Michelin-starred dining in ${cityLabel}. One of the best tables in the city — book ahead.`
  if (isBib)  return 'Michelin Bib Gourmand pick. Exceptional food at a great price — a local favorite.'
  if (category === 'bar' || category === 'night_club') {
    if (rating >= 4.7) return `One of ${cityLabel}'s best-rated bars. Great craft drinks and an atmosphere people keep coming back for.`
    if (rating >= 4.5) return `A top-rated ${cityLabel} bar. Great for date night or a night out with friends.`
    if (hot >= 8) return 'Hot spot tonight. Buzzing atmosphere and solid drinks.'
    return `A reliable ${cityLabel} bar worth a visit. Check their specials tonight.`
  }
  if (category === 'restaurant') {
    if (rating >= 4.7) return `One of ${cityLabel}'s highest-rated restaurants. A must-visit for serious food lovers.`
    if (rating >= 4.5) return 'Consistently excellent food and service. A local go-to for special nights.'
    if (priceLevel >= 3) return `Upscale ${cityLabel} dining with refined flavors and a thoughtful wine list.`
    if (priceLevel <= 1) return 'Great food without the price tag. A local gem that draws crowds.'
    return 'Well-loved by locals for quality food and good vibes.'
  }
  if (category === 'cafe') {
    if (rating >= 4.6) return `One of ${cityLabel}'s top-rated coffee spots. Perfect for working or catching up.`
    return 'Good coffee and a chill vibe. A solid spot to slow down.'
  }
  return `A standout ${cityLabel} spot worth adding to your night.`
}

