export function getFeaturedVenuesByCity(city: string): Venue[] {
  if (city === 'monterrey') return MTY_FEATURED_VENUES
  if (city === 'atlanta')   return ATL_FEATURED_VENUES
  if (city === 'nyc')       return NYC_FEATURED_VENUES
  if (city === 'dallas')    return DAL_FEATURED_VENUES
  if (city === 'miami')     return MIA_FEATURED_VENUES
  if (city === 'cdmx')      return CDMX_FEATURED_VENUES
  if (city === 'chicago')   return CHI_FEATURED_VENUES
  if (city === 'la')        return LA_FEATURED_VENUES
  if (city === 'houston')   return HOU_FEATURED_VENUES
  return FEATURED_VENUES
}

