export const MOOD_FILTERS: Record<string, { label: string; categories?: string[]; tags?: string[] }> = {
  all:    { label: 'All Vibes' },
  date:   { label: 'Date Night',  tags: ['Date Night', 'Upscale', 'Speakeasy', 'Omakase'] },
  happy:  { label: 'Happy Hour',  tags: ['happyHour'] },
  music:  { label: 'Live Music',  tags: ['Live Music', 'Jazz', 'Country'] },
  dance:  { label: 'Dancing',     tags: ['Dancing', 'Nightlife', 'Tango'] },
  sports: { label: 'Sports Bar',  tags: ['Sports Bar'] },
  brunch: { label: 'Brunch',      categories: ['cafe', 'restaurant'] },
  roof:   { label: 'Rooftop',     tags: ['Rooftop', 'Pool Bar'] },
}

export function filterVenues(venues: Venue[], mood: string): Venue[] {
  if (mood === 'all') return venues
  const config = MOOD_FILTERS[mood]
  if (!config) return venues
  return venues.filter(v => {
    if (config.categories && config.categories.includes(v.category)) return true
    if (config.tags) {
      if (config.tags.includes('happyHour')) return !!v.happyHour
      return config.tags.some(t => v.tags.includes(t))
    }
    return false
  })
}

